<?php require 'config.php';login_required();$u=user();if(isset($_GET['join'])){$s=$pdo->prepare('INSERT IGNORE INTO enrollments(user_id,circle_id,status) VALUES(?,?,"active")');$s->execute([$u['id'],(int)$_GET['join']]);header('Location: circles.php');exit;}$circles=$pdo->query('SELECT c.*,u.name creator,(SELECT COUNT(*) FROM enrollments e WHERE e.circle_id=c.id AND e.status="active") total FROM circles c LEFT JOIN users u ON u.id=c.created_by ORDER BY c.created_at DESC')->fetchAll();header_html('الحلقات');if(in_array($u['role'],['admin','teacher'],true))echo '<a class="button" href="circle_form.php">إنشاء حلقة جديدة</a>';?><div class="cards"><?php foreach($circles as $c): ?><article class="card"><h2><?=e($c['title'])?></h2><p><?=e($c['description'])?></p><p>المستوى: <?=e($c['level'])?> | الموعد: <?=e($c['days'])?> <?=e($c['time'])?></p><p>عدد الطلاب: <?=$c['total']?></p><?php if($u['role']==='student'): ?><a class="button" href="?join=<?=$c['id']?>">التسجيل في الحلقة</a><?php endif;if(in_array($u['role'],['admin','teacher'],true)): ?><a class="button secondary" href="attendance.php?circle=<?=$c['id']?>">الحضور</a><?php endif; ?></article><?php endforeach;if(!$circles): ?><p>لا توجد حلقات بعد.</p><?php endif; ?></div><?php footer_html(); ?>